const PREFIX = { general: 'gk', science: 'sc', geography: 'ge', games: 'ga', food: 'fo', animals: 'an', space: 'sp' };

export const TIERS = Object.freeze([
  Object.freeze({ id: 'easy', name: 'Easy', emoji: '🟢', mult: 1 }),
  Object.freeze({ id: 'medium', name: 'Medium', emoji: '🟡', mult: 1.25 }),
  Object.freeze({ id: 'hard', name: 'Hard', emoji: '🔴', mult: 1.5 }),
]);

const TIER_IDS = new Set(TIERS.map((t) => t.id));

export const QUESTIONS = Object.freeze(
  Object.entries(ROWS).flatMap(([cat, rows]) =>
    rows.map(([q, a, w1, w2, w3, tier], i) =>
      Object.freeze({ id: `${PREFIX[cat]}${String(i + 1).padStart(2, '0')}`, cat, q, a, w: Object.freeze([w1, w2, w3]), tier: TIER_IDS.has(tier) ? tier : 'easy' }),
    ),
  ),
);

const BY_ID = new Map(QUESTIONS.map((q) => [q.id, q]));

export function questionById(id) {
  return BY_ID.get(id) || null;
}
